SENTINELS = {
    "LEDGER_CONSOLIDATED.md": "#### [L-510] Obsolete code: how it is marked",
    "documentation/WHERE_WE_ARE.md": "the three comets ruled Nov 3",
}
PAGE = "documentation/WHERE_WE_ARE.md"
MARKER = "--- Your run record below this line"
CAP = 130


def fail(msg):
    print(msg)
    print("NOTHING was written. Undo is not needed.")
    sys.exit(1)


def main():
    staged = []
    for rel, edits in EDITS:
        path = os.path.join(HERE, *rel.split("/"))
        if not os.path.isfile(path):
            fail("ERROR: not found: %s -- is this file in the orrery folder "
                 "(palomas_orrery_for_github)?" % path)
        raw = open(path, "rb").read()
        crlf = b"\r\n" in raw
        text = raw.replace(b"\r\n", b"\n").decode("utf-8")
        if SENTINELS[rel] in text:
            fail("ERROR: %s already carries this patch's change; this patch "
                 "has run. Nothing more to do." % rel)
        for k, (old, new) in enumerate(edits):
            n = text.count(old)
            if n != 1:
                fail("ANCHOR FAIL in %s, edit %d of %d: expected 1 match, "
                     "found %d. The file changed since b09989e0 at a line "
                     "this patch edits; send the session this output."
                     % (rel, k + 1, len(edits), n))
            text = text.replace(old, new)
        staged.append((rel, path, text, crlf, len(edits)))
    for rel, path, text, crlf, n in staged:
        open(path, "wb").write(text.encode("utf-8"))
        print("ok  %s (%d edits)" % (rel, n))
        if crlf:
            print("note: %s was CRLF in the working copy; written LF" % rel)
        bad = sum(1 for c in text if ord(c) > 127)
        if bad:
            print("note: %s holds %d non-ASCII character(s) this patch did "
                  "not add" % (rel, bad))
        if rel == PAGE:
            lines = text.split("\n")
            above = next((i for i, l in enumerate(lines)
                          if l.startswith(MARKER)), len(lines))
            if above > CAP:
                print("note: Where We Are has %d lines above the run-record "
                      "marker; its cap is %d (it had 175 before this patch)"
                      % (above, CAP))
    print(DONE % len(staged))
    print("")
    print("Your run order:")
    print("  1. Open documentation\\WHERE_WE_ARE.md and read the box.")
    print("  2. Move this file into documentation\\.")
    print("  3. Commit and push the orrery in GitHub Desktop, with")
    print("     HANDOFF_L484_after_talk_20261103.md and your run record copy.")


if __name__ == "__main__":
    main()
